import React, { Component } from 'react'
import StepWrapper from '../../../components/Steps'
import Step1StyleWrapper from './index.style'
import { Row, Col, Form, Button, notification } from 'antd'
import { connect } from 'react-redux'
import { getFormItems } from '../../../components/formItem'
import productcreationActions from '../../../../../redux/productConfig/actions'
import { get, size, isEqual } from 'lodash'
const {
  getProductCategories,
  createProductAction,
  resetProductConfigRedux
} = productcreationActions
class Step1 extends Component {
  state ={
    category: [],
    formBody: {}
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      categoryList,
      categoriesMessage,
      addProductData,
      addProductDataMessage
    } = nextProps
    if (categoriesMessage === 'success') {
      this.setState({
        category: get(categoryList, 'data.details', [])
      })
      this.props.resetProductConfigRedux(['getProductCategoriesMessage'])
    }

    if (addProductDataMessage === 'success') {
      const data = {
        ...this.state.formBody,
        id: get(addProductData, 'data.details.id', '')
      }
      // window.sessionStorage.setItem('Step1', JSON.stringify(data)) // TODO : remove the localstorage

      notification.success({
        message: 'Success',
        description: 'Product created successfully'
      })
      this.props.resetProductConfigRedux(['addconfigProductMessage'])
      this.setState({
        formBody: data
      }, () => {
        this.nextPage()
      })
    }
    if (addProductDataMessage !== 'success' && addProductDataMessage !== undefined) {
      window.sessionStorage.removeItem('Step1')
      notification.error({
        message: 'Error',
        description: get(addProductDataMessage, 'data.errors[0].description', '')
      })
      this.props.resetProductConfigRedux(['addconfigProductMessage'])
    }
  }

  componentDidMount () {
    const { location, form } = this.props
    this.props.getProductCategories()
    const payload = get(location, 'state.step1Data', {})
    if (size(payload) > 0) {
      this.setState({
        formBody: payload
      })
      Object.keys(payload).forEach(item => {
        form.setFieldsValue({
          [item]: payload[item]
        })
      })
    }
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  submitHandler = async (e) => {
    e.preventDefault()
    const { form } = this.props
    const { formBody } = this.state
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    // TODO: Need to handle next case when user come back from step 2

    if (size(formBody) > 0 && isEqual(formBody, form.getFieldsValue())) {
      this.nextPage()
    } else {
      const formBody = form.getFieldsValue()
      this.setState({
        formBody
      })
      this.props.createProductAction({ body: formBody })
    }
  }

  nextPage = () => {
    const { history } = this.props
    history.push({
      pathname: '/product-config/create-product/2/table',
      state: {
        formName: 'Step1',
        formData: {
          step1Data: this.state.formBody
        }
      }
    })
  }

  cancelWizard = () => {
    const { history } = this.props
    history.push('/product-config')
  }

  componentWillUnmount () {
    window.sessionStorage.removeItem('Step1')    // TODO: remove the window.sessionStorage
  }

  render () {
    const { category } = this.state
    const { categoryListLoading, categoriesError, createProductLoading, createProductError } = this.props
    return (
      <Row type='flex'>
        <Col span={24}>
          <StepWrapper
            current={0}
          >
            <Step1StyleWrapper>
              <Form
                hideRequiredMark
                className='form-1'
                onSubmit={this.submitHandler}
              >
                <Row type='flex'>
                  <Col span={24}>
                    <p>Product code</p>
                  </Col>
                  <Col span={24}>
                    {
                      getFormItems.call(this, {
                        formName: 'code',
                        type: 'alphanumeric',
                        required: true,
                        className: 'small-size'
                        // validator: validator.checkValidator
                      })
                    }
                  </Col>
                </Row>
                <Row type='flex'>
                  <Col span={24}>
                    <p>Product name</p>
                  </Col>
                  <Col span={24}>
                    {
                      getFormItems.call(this, {
                        formName: 'name',
                        type: 'alphanumeric',
                        required: true,
                        className: 'small-size'
                        // validator: validator.checkValidator
                      })
                    }
                  </Col>
                </Row>
                <Row type='flex'>
                  <Col span={24}>
                    <p>Category</p>
                  </Col>
                  <Col span={24}>
                    {
                      getFormItems.call(this, {
                        formName: 'category_id',
                        type: 'choices',
                        required: true,
                        options: category || [],
                        optionKey: 'id',
                        loading: categoryListLoading && !categoriesError,
                        optionDisplayName: 'name',
                        className: 'small-size'
                      })
                    }
                  </Col>
                </Row>
                <Row type='flex'>
                  <Col span={24} className='step1_button-section'>
                    <Button onClick={this.cancelWizard}>Cancel</Button>
                    <Button
                      loading={createProductLoading && !createProductError}
                      className='next-button'
                      type='primary'
                      htmlType='submit'>
                      Next
                    </Button>
                  </Col>
                </Row>
              </Form>
            </Step1StyleWrapper>
          </StepWrapper>
        </Col>
      </Row>
    )
  }
}
const WrappedStep1Data = Form.create()(Step1)
export default connect(
  state => ({
    addProductData: state.ProductConfigurable.addconfigProductData,
    addProductDataMessage: state.ProductConfigurable.addconfigProductMessage,
    categoryList: state.ProductConfigurable.getProductCategories,
    categoryListLoading: state.Loading.GET_PRODUCT_CATEGORIES,
    categoriesError: state.Error.GET_PRODUCT_CATEGORIES,
    categoriesMessage: state.ProductConfigurable.getProductCategoriesMessage,
    createProductLoading: state.Loading.CREATE_NEW_PRODUCT,
    createProductError: state.Error.CREATE_NEW_PRODUCT
  }), {
    getProductCategories,
    resetProductConfigRedux,
    createProductAction
  }
)(WrappedStep1Data)
